 *
 * @param {string} url The URL from which to fetch the data.
 * @returns {Promise<object>} A Promise that resolves with the parsed JSON data.
 * @throws {Error} Throws an error if the network request fails or the response is not OK.
 */
async function fetchJsonData(url) {
  try {
    // 1. Perform the fetch request
    const response = await fetch(url);

    // 2. Check if the response status is OK (status code 200-299)
    if (!response.ok) {
      // Throw an error with status information if the HTTP status is not successful
      throw new Error(`HTTP error! Status: ${response.status} - ${response.statusText || 'Unknown error'}`);
    }

    // 3. Parse the response body as JSON
    const data = await response.json();

    // 4. Return the parsed data
    return data;

  } catch (error) {
    // Handle network errors (e.g., DNS failure, no connection) or errors thrown above
    console.error("Error fetching JSON data:", error.message);
    // Re-throw the error so the calling function knows the operation failed
    throw error;
  }
}

