/**
 * Chunks an array into smaller arrays of size n.
 *
 * @param {Array<any>} array The array to chunk.
 * @param {number} n The desired chunk size.
 * @returns {Array<Array<any>>} An array of arrays (chunks).
 */
function chunkArrayLoop(array, n) {
  if (!Array.isArray(array) || n <= 0) {
    return []; // Handle invalid input
  }

  const chunkedArray = [];
  let index = 0;

  while (index < array.length) {
    // Use slice to extract the portion from the current index up to index + n
    chunkedArray.push(array.slice(index, index + n));
    // Move the index forward by the chunk size
    index += n;
  }

  return chunkedArray;
}

